sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   //Type appropriate comment here, and begin script below
	g_form.getReference('caller_id', function(caller){
		if (caller.getValue('vip') === 'true'){
			g_form.showFieldMsg('caller_id','This user is VIP','info');
			//alert('This user is VIP');
		}else{
			g_form.hideFieldMsg('caller_id');
			//alert('This user is not VIP');
		}
	});
}
